(()=>{'use strict';const section=document.querySelector('.longshot'),$=s=>section.querySelector(s),stage=$('.ls-stage'),film=$('.ls-film'),world=$('.ls-world'),dialog=document.querySelector('#ls-brief'),steps=[...section.querySelectorAll('[data-ls-step]')],stops=[0,.23,.46,.69,.94];
const copy=[['01 / CONNECT YOUR AI','Be in the conversation. Capture what matters.','Double-press to record. Press once during recording to highlight a moment.'],['02 / CONNECT YOUR AI','Your conversation. Ready for AI.','Vocci turns your recording into a transcript and summary, with the moments you marked along the way.'],['03 / CONNECT YOUR AI','Less explaining. More getting done.','Connect Vocci to your AI. Turn client conversations into clear next steps for your team—without copying and pasting.'],['04 / ASK VOCCI AI','A task on your mind? Just ask Vocci AI.','Press and hold to tell Vocci AI what you need.'],['05 / ASK VOCCI AI','Keep the work moving.','Vocci AI works with your connected apps to carry out tasks—like sending a follow-up in Slack. Review and confirm in the Vocci app when needed.']];
let sent=false,previous=-1,frame=0;function update(){frame=0;let p=Math.max(0,Math.min(1,-section.getBoundingClientRect().top/Math.max(1,section.offsetHeight-stage.offsetHeight))),beat=p<.13?0:p<.35?1:p<.58?2:p<.82?3:4;film.style.transform=`translate3d(${-p*Math.max(0,film.scrollWidth-world.clientWidth)}px,0,0)`;
if(previous!==beat){previous=beat;section.dataset.beat=beat;$('#ls-label').textContent=copy[beat][0];$('#ls-line').textContent=sent&&beat===4?'Sent. On with your day.':copy[beat][1];$('#ls-detail').textContent=copy[beat][2];$('.ls-connected').hidden=beat>2;$('.ls-app-zone').hidden=beat<3;$('.ls-welcome').hidden=true;$('.ls-chat').hidden=false;$('.ls-document').hidden=beat<4;$('.ls-confirm').hidden=beat!==4||sent;$('.ls-actions').hidden=beat!==4||sent;$('#ls-response-text').textContent=beat===3?'I’ll use your recent meeting to build a launch brief.':sent?'Sent to your team. ✓':'Your launch brief is ready.';$('#ls-composer-text').textContent=beat===3?'Voice command received · Vocci Ring':'Ask any question…';$('#connected-title').textContent=['Launch planning','Transcript & summary','Your AI, with context'][Math.min(beat,2)];$('#connected-body').textContent=['Double-press to start and end recording.','Decisions, action items and highlighted moments.','“Use my Vocci meeting to draft the team’s next steps.”'][Math.min(beat,2)];$('#connected-label').textContent=['MEETING / CAPTURE','CONTEXT / READY','CONNECTED THROUGH MCP'][Math.min(beat,2)];$('#connected-result').textContent=['Capture the decisions while you stay in the conversation.','Launch goals · Audience · Timeline','Your authorized AI can retrieve the conversation and work from what was actually said.'][Math.min(beat,2)];steps.forEach((b,i)=>{if(i===beat)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}$('.ls-progress i').style.width=p*100+'%'}
function schedule(){if(!frame)frame=requestAnimationFrame(update)}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);section.querySelectorAll('img').forEach(i=>i.addEventListener('load',schedule));steps.forEach(b=>b.addEventListener('click',()=>scrollTo({top:section.offsetTop+stops[+b.dataset.lsStep]*(section.offsetHeight-stage.offsetHeight),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})));$('#ls-review').addEventListener('click',()=>dialog.showModal());document.querySelector('#ls-close').addEventListener('click',()=>dialog.close());$('#ls-send').addEventListener('click',()=>{sent=true;previous=-1;update()});update()})();
